ue,"content_key":"APSTATS-HDG-2026-GRAPH-036","rubric_type":"spatial","label_status":"ai_provisional_unapproved","rights_status":"independently_authored_synthetic_research_seed_unverified","stimulus_table":[{"Yield loss (%)":33,"Irrigation (in)":0.5},{"Yield loss (%)":30,"Irrigation (in)":1},{"Yield loss (%)":38,"Irrigation (in)":1.5},{"Yield loss (%)":23,"Irrigation (in)":2},{"Yield loss (%)":21,"Irrigation (in)":2.5},{"Yield loss (%)":29,"Irrigation (in)":3},{"Yield loss (%)":28,"Irrigation (in)":3.5},{"Yield loss (%)":14,"Irrigation (in)":4},{"Yield loss (%)":14,"Irrigation (in)":4.5}],"evaluator_strategy":"human_shadow","capture_instruction":"Original research seed for hand-drawn AP Statistics graph-response grading. Do not expose criterion definitions to the person drawing the graph.","expected_graph_spec":{"x_axis":"weekly irrigation (inches)","y_axis":"yield loss from drought stress (%)","representation":"scatterplot with trend line"},"practice_modality":"supplemental_hand_drawn"},"canonical_answer_1":"Scatterplot shows a moderately strong negative roughly linear association between irrigation amount and drought-related yield loss (r ≈ -0.765). The least-squares line is approximately yield loss = 37.06 - 4.60 × irrigation; a reasonable trend line passes near (0.5, 35) and (4.5, 16).","explanation":null,"choices":[]}},{"content_key":"APSTATS-MCQ-002-CAL","source_version_id":"f8ec7c37-02ef-4086-8ff2-1171c2035825","source_content_hash":"0ae99d62d483278a0139c4c289627e4428d72865acd8e15eb38075c33c52e945","topic_code":"1.9","skill_code":"4.C","agreement":"majority_earned","required_units":[1],"primary_unit":1,"difficulty":"Hard","proposed_content":null},{"content_key":"APSTATS-MCQ-007","source_version_id":"7921ecab-7098-4d9f-92ad-6ffc69279113","source_content_hash":"2a21c083500ba94c77000733097a6935e8709d5b781a4464d78443445cee76a8","topic_code":"2.7","skill_code":"3.C","agreement":"deterministic_single_candidate","required_units":[2],"primary_unit":2,"difficulty":"Medium","proposed_content":{"stem":"What is the probability that the wheel lands on red on the next spin?","stimulus":"At a local carnival game, a balanced wheel has ten equal sectors, three of them red. Each spin is independent. A player has just watched the wheel land on red four times in a row.","prompt_json":{"stem":"What is the probability that the wheel lands on red on the next spin?","choices":[{"rationale":"This is the gambler's fallacy -- independent events have no memory, so past outcomes do not change the probability of the next spin.","choice_key":"A","is_correct":false,"choice_text":"Less than 0.3, because red is \"due\" to be balanced out by other colors soon."},{"rationale":"Since the spins are stated to be independent, the probability of red on any single spin remains 0.3 regardless of the outcomes of previous spins.","choice_key":"B","is_correct":true,"choice_text":"0.3, because each spin is independent of previous spins."},{"rationale":"This treats a run of independent outcomes as evidence of a changing probability, which contradicts the stated independence of the spins.","choice_key":"C","is_correct":false,"choice_text":"Greater than 0.3, because landing on red four times in a row suggests the wheel is more likely to land on red."},{"rationale":"This answers a different question (the probability of a specific five-spin sequence) rather than the probability of the single next spin.","choice_key":"D","is_correct":false,"choice_text":"0.3 to the fifth power, because the probability of five reds in a row must be calculated."}],"modules":["2"],"subject":"AP Statistics","stimulus":"At a local carnival game, a balanced wheel has ten equal sectors, three of them red. Each spin is independent. A player has just watched the wheel land on red four times in a row.","item_type":"mcq","subtopics":["Unit 2: Independence and the Gambler’s Fallacy"],"content_key":"APSTATS-MCQ-007","intended_difficulty":"Medium"},"canonical_answer_1":null,"explanation":null,"choices":[{"choice_key":"A","choice_text":"Less than 0.3, because red is \"due\" to be balanced out by other colors soon.","is_correct":false,"rationale":"This is the gambler's fallacy -- independent events have no memory, so past outcomes do not change the probability of the next spin."},{"choice_key":"B","choice_text":"0.3, because each spin is independent of previous spins.","is_correct":true,"rationale":"Since the spins are stated to be independent, the probability of red on any single spin remains 0.3 regardless of the outcomes of previous spins."},{"choice_key":"C","choice_text":"Greater than 0.3, because landing on red four times in a row suggests the wheel is more likely to land on red.","is_correct":false,"rationale":"This treats a run of independent outcomes as evidence of a changing probability, which contradicts the stated independence of the spins."},{"choice_key":"D","choice_text":"0.3 to the fifth power, because the probability of five reds in a row must be calculated.","is_correct":false,"rationale":"This answers a different question (the probability of a specific five-spin sequence) rather than the probability of the single next spin."}]}},{"content_key":"APSTATS-MCQ-007-CAL","source_version_id":"1a3ef4df-21ce-4d21-aaff-91bf7b826fd2","source_content_hash":"0ae99d62d483278a0139c4c289627e4428d72865acd8e15eb38075c33c52e945","topic_code":"2.7","skill_code":"3.C","agreement":"deterministic_single_candidate","required_units":[2],"primary_unit":2,"difficulty":"Medium","proposed_content":{"stem":"What is the probability that the wheel lands on red on the next spin?","stimulus":"At a local carnival game, a balanced wheel has ten equal sectors, three of them red, and each spin is independent. A player has just watched the wheel land on red four times in a row.","prompt_json":{"modules":["2"],"subject":"AP Statistics","subtopics":["Unit 2: Independence and the Gambler's Fallacy"],"rubric_type":"mcq","evaluator_strategy":"rule_based_mcq","source_content_key":"APSTATS-MCQ-007","intended_difficulty":"Medium","collision_resolution":"renamed_with_cal_suffix_to_avoid_published_smoke_batch_collision","phase_c_publish_packet":"2026-07-11","stem":"What is the probability that the wheel lands on red on the next spin?","stimulus":"At a local carnival game, a balanced wheel has ten equal sectors, three of them red, and each spin is independent. A player has just watched the wheel land on red four times in a row.","choices":[{"rationale":"This is the gambler's fallacy -- independent events have no memory, so past outcomes do not change the probability of the next spin.","choice_key":"A","is_correct":false,"choice_text":"Less than 0.3, because red is \"due\" to be balanced out by other colors soon."},{"rationale":"Since the spins are stated to be independent, the probability of red on any single spin remains 0.3 regardless of the outcomes of previous spins.","choice_key":"B","is_correct":true,"choice_text":"0.3, because each spin is independent of previous spins."},{"rationale":"This treats a run of independent outcomes as evidence of a changing probability, which contradicts the stated independence of the spins.","choice_key":"C","is_correct":false,"choice_text":"Greater than 0.3, because landing on red four times in a row suggests the wheel is more likely to land on red."},{"rationale":"This answers a different question (the probability of a specific five-spin sequence) rather than the probability of the single next spin.","choice_key":"D","is_correct":false,"choice_text":"0.3 to the fifth power, because the probability of five reds in a row must be calculated."}]},"canonical_answer_1":null,"explanation":"Since the spins are stated to be independent, the probability of red on any single spin remains 0.3 regardless of the outcomes of previous spins.","choices":[{"rationale":"This is the gambler's fallacy -- independent events have no memory, so past outcomes do not change the probability of the next spin.","choice_key":"A","is_correct":false,"choice_text":"Less than 0.3, because red is \"due\" to be balanced out by other colors soon."},{"rationale":"Since the spins are stated to be independent, the probability of red on any single spin remains 0.3 regardless of the outcomes of previous spins.","choice_key":"B","is_correct":true,"choice_text":"0.3, because each spin is independent of previous spins."},{"rationale":"This treats a run of independent outcomes as evidence of a changing probability, which contradicts the stated independence of the spins.","choice_key":"C","is_correct":false,"choice_text":"Greater than 0.3, because landing on red four times in a row suggests the wheel is more likely to land on red."},{"rationale":"This answers a different question (the probability of a specific five-spin sequence) rather than the probability of the single next spin.","choice_key":"D","is_correct":false,"choice_text":"0.3 to the fifth power, because the probability of five reds in a row must be calculated."}]}},{"content_key":"APSTATS-MCQ-010","source_version_id":"c82cd294-e08a-4aa9-b7f7-ed3fa7369d33","source_content_hash":"7fc137412da39f0875c906d3cd907f340132915260e123749ed16739ac114b79","topic_code":"3.2","skill_code":"4.E","agreement":"unanimous","required_units":[3],"primary_unit":3,"difficulty":"Hard","proposed_content":{"stem":"Why is it inappropriate to use a normal approximation for the sampling distribution of p-hat in this situation?","stimulus":"A quality control engineer wants to use a normal approximation for the sampling distribution of the sample proportion of defective items in a random sample of size n = 40 from a manufacturing process where the true defect rate is p = 0.03.","prompt_json":{"stem":"Why is it inappropriate to use a normal approximation for the sampling distribution of p-hat in this situation?","choices":[{"rationale":"The success-failure condition requires both np and n(1-p) to be at least 10; here np = 1.2, which fails the condition, so the normal approximation is not justified.","choice_key":"A","is_correct":true,"choice_text":"np = 40(0.03) = 1.2, which is less than 10, so the success-failure condition is not met and the sampling distribution of p-hat would be skewed, not approximately normal."},{"rationale":"Appropriateness depends on np and n(1-p), not on the sample size n alone; a sample of 40 could be adequate for a different value of p.","choice_key":"B","is_correct":false,"choice_text":"The sample size 40 is too small to ever use a normal approximation, regardless of the value of p."},{"rationale":"This confuses the parameter/statistic distinction with the actual condition being checked; the success-failure condition uses p to check np and n(1-p), regardless of p being a parameter.","choice_key":"C","is_correct":false,"choice_text":"The population defect rate p = 0.03 is a parameter, not a statistic, so the normal approximation does not apply to parameters."},{"rationale":"The stimulus states the sample is random; this introduces an assumption violation that isn't actually present in the scenario.","choice_key":"D","is_correct":false,"choice_text":"Random sampling was not used, so no approximation is valid."}],"modules":["3"],"subject":"AP Statistics","stimulus":"A quality control engineer wants to use a normal approximation for the sampling distribution of the sample proportion of defective items in a random sample of size n = 40 from a manufacturing process where the true defect rate is p = 0.03.","item_type":"mcq","subtopics":["Unit 3: Sampling Distribution of a Sample Proportion"],"content_key":"APSTATS-MCQ-010","intended_difficulty":"Hard"},"canonical_answer_1":null,"explanation":null,"choices":[{"choice_key":"A","choice_text":"np = 40(0.03) = 1.2, which is less than 10, so the success-failure condition is not met and the sampling distribution of p-hat would be skewed, not approximately normal.","is_correct":true,"rationale":"The success-failure condition requires both np and n(1-p) to be at least 10; here np = 1.2, which fails the condition, so the normal approximation is not justified."},{"choice_key":"B","choice_text":"The sample size 40 is too small to ever use a normal approximation, regardless of the value of p.","is_correct":false,"rationale":"Appropriateness depends on np and n(1-p), not on the sample size n alone; a sample of 40 could be adequate for a different value of p."},{"choice_key":"C","choice_text":"The population defect rate p = 0.03 is a parameter, not a statistic, so the normal approximation does not apply to parameters.","is_correct":false,"rationale":"This confuses the parameter/statistic distinction with the actual condition being checked; the success-failure condition uses p to check np and n(1-p), regardless of p being a parameter."},{"choice_key":"D","choice_text":"Random sampling was not used, so no approximation is valid.","is_correct":false,"rationale":"The stimulus states the sample is random; this introduces an assumption violation that isn't actually present in the scenario."}]}},{"content_key":"APSTATS-MCQ-012","source_version_id":"28f514dd-4acb-437f-9430-88457c72bf1f","source_content_hash":"f8c0dbeb52c9ee637ebbb9c1c15bf860dc9c188bdaf23019de47fcb49d853abd","topic_code":"3.13","skill_code":"4.G","agreement":"unanimous","required_units":[1,3],"primary_unit":3,"difficulty":"Hard","proposed_content":{"stem":"Using a significance level of alpha = 0.05, which is the correct conclusion in context?","stimulus":"A company tests whether a new checkout design increases the proportion of customers who complete a purchase. In a randomized experiment, 620 customers were shown the new design and 248 completed a purchase; 580 customers were shown the old design and 203 completed a purchase. A two-proportion z-test with the alternative hypothesis that the new design's completion proportion is greater than the old design's completion proportion yields a p-value of approximately 0.037.","prompt_json":{"stem":"Using a significance level of alpha = 0.05, which is the correct conclusion in context?","choices":[{"rationale":"This is the classic p-value misinterpretation; a p-value is the probability of the observed (or more extreme) sample results assuming the null hypothesis is true, not the probability that the null hypothesis itself is true.","choice_key":"A","is_correct":false,"choice_text":"Because p = 0.037 is less than 0.05, there is a 3.7% probability that the old and new designs have the same true completion proportion."},{"rationale":"Because this was a randomized experiment (customers were randomly assigned to see each design) and the p-value is below alpha, a causal conclusion in context is statistically justified.","choice_key":"B","is_correct":true,"choice_text":"Because p = 0.037 is less than 0.05, there is convincing evidence that the new checkout design causes a higher completion proportion than the old design."},{"rationale":"This misreads the stimulus, which explicitly describes a randomized experiment; causal language is actually appropriate here, unlike in an observational study.","choice_key":"C","is_correct":false,"choice_text":"Because p = 0.037 is less than 0.05, there is convincing evidence that the new design is associated with a higher completion proportion, but causation cannot be concluded since this was not a controlled experiment."},{"rationale":"The formal decision rule compares p to alpha directly; since 0.037 < 0.05, the result is statistically significant regardless of how close the p-value is to the threshold.","choice_key":"D","is_correct":false,"choice_text":"Because p = 0.037 is close to 0.05, the results are inconclusive and no decision can be made at alpha = 0.05."}],"modules":["3"],"subject":"AP Statistics","stimulus":"A company tests whether a new checkout design increases the proportion of customers who complete a purchase. In a randomized experiment, 620 customers were shown the new design and 248 completed a purchase; 580 customers were shown the old design and 203 completed a purchase. A two-proportion z-test with the alternative hypothesis that the new design's completion proportion is greater than the old design's completion proportion yields a p-value of approximately 0.037.","item_type":"mcq","subtopics":["Unit 3: Two-Proportion z-Test—Interpreting a Significant Result from a Randomized Experiment"],"content_key":"APSTATS-MCQ-012","intended_difficulty":"Hard"},"canonical_answer_1":null,"explanation":null,"choices":[{"choice_key":"A","choice_text":"Because p = 0.037 is less than 0.05, there is a 3.7% probability that the old and new designs have the same true completion proportion.","is_correct":false,"rationale":"This is the classic p-value misinterpretation; a p-value is the probability of the observed (or more extreme) sample results assuming the null hypothesis is true, not the probability that the null hypothesis itself is true."},{"choice_key":"B","choice_text":"Because p = 0.037 is less than 0.05, there is convincing evidence that the new checkout design causes a higher completion proportion than the old design.","is_correct":true,"rationale":"Because this was a randomized experiment (customers were randomly assigned to see each design) and the p-value is below alpha, a causal conclusion in context is statistically justified."},{"choice_key":"C","choice_text":"Because p = 0.037 is less than 0.05, there is convincing evidence that the new design is associated with a higher completion proportion, but causation cannot be concluded since this was not a controlled experiment.","is_correct":false,"rationale":"This misreads the stimulus, which explicitly describes a randomized experiment; causal language is actually appropriate here, unlike in an observational study."},{"choice_key":"D","choice_text":"Because p = 0.037 is close to 0.05, the results are inconclusive and no decision can be made at alpha = 0.05.","is_correct":false,"rationale":"The formal decision rule compares p to alpha directly; since 0.037 < 0.05, the result is statistically significant regardless of how close the p-value is to the threshold."}]}},{"content_key":"APSTATS-MCQ-017","source_version_id":"a03cd184-777a-4bf3-92fe-49fcc9fff0b7","source_content_hash":"e835b9a0f34e833174ede6554ac272d701dee6cfc4a6d0068ad20afeac79d7f5","topic_code":"5.5","skill_code":"4.D","agreement":"unanimous","required_units":[5],"primary_unit":5,"difficulty":"Medium","proposed_content":{"stem":"Which statement correctly interprets the slope of the regression line in context?","stimulus":"A researcher fits a least-squares regression line relating weekly hours of exercise to resting heart rate for a random sample of 45 adults. The estimated slope is -1.8 beats per minute per additional hour of exercise per week.","prompt_json":{"stem":"Which statement correctly interprets the slope of the regression line in context?","choices":[{"choice_key":"A","choice_text":"For each additional hour of exercise per week, the model predicts a resting heart rate about 1.8 beats per minute lower, on average.","is_correct":true,"rationale":"A negative slope of -1.8 means the predicted response decreases by 1.8 beats per minute for each one-hour increase in weekly exercise."},{"choice_key":"B","choice_text":"Each additional hour of exercise per week causes resting heart rate to fall by exactly 1.8 beats per minute.","is_correct":false,"rationale":"A regression association from an observational sample does not establish causation or an exact change for each adult."},{"choice_key":"C","choice_text":"Resting heart rate increases by 1.8 beats per minute for each additional hour of exercise per week.","is_correct":false,"rationale":"The slope is negative, so the fitted value decreases rather than increases."},{"choice_key":"D","choice_text":"For each one-beat-per-minute decrease in resting heart rate, the model predicts 1.8 more hours of exercise per week.","is_correct":false,"rationale":"This reverses the explanatory and response variables; the fitted line predicts resting heart rate from exercise hours."}],"modules":["5"],"subject":"AP Statistics","stimulus":"A researcher fits a least-squares regression line relating weekly hours of exercise to resting heart rate for a random sample of 45 adults. The estimated slope is -1.8 beats per minute per additional hour of exercise per week.","item_type":"mcq","subtopics":["Unit 5, Topic 5.5: Interpret the slope of a least-squares regression line"],"content_key":"APSTATS-MCQ-017","intended_difficulty":"Medium"},"canonical_answer_1":null,"explanation":"For each additional hour of exercise per week, the fitted line predicts a resting heart rate about 1.8 beats per minute lower, on average. These observational data do not establish causation or an exact individual change.","choices":[{"choice_key":"A","choice_text":"For each additional hour of exercise per week, the model predicts a resting heart rate about 1.8 beats per minute lower, on average.","is_correct":true,"rationale":"A negative slope of -1.8 means the predicted response decreases by 1.8 beats per minute for each one-hour increase in weekly exercise."},{"choice_key":"B","choice_text":"Each additional hour of exercise per week causes resting heart rate to fall by exactly 1.8 beats per minute.","is_correct":false,"rationale":"A regression association from an observational sample does not establish causation or an exact change for each adult."},{"choice_key":"C","choice_text":"Resting heart rate increases by 1.8 beats per minute for each additional hour of exercise per week.","is_correct":false,"rationale":"The slope is negative, so the fitted value decreases rather than increases."},{"choice_key":"D","choice_text":"For each one-beat-per-minute decrease in resting heart rate, the model predicts 1.8 more hours of exercise per week.","is_correct":false,"rationale":"This reverses the explanatory and response variables; the fitted line predicts resting heart rate from exercise hours."}]}}]$task0050_payload$::jsonb) as x(
  content_key text, source_version_id uuid, source_content_hash text,
  topic_code text, skill_code text, agreement text, required_units integer[],
  primary_unit integer, difficulty text, proposed_content jsonb
);

create temporary table release_target on commit drop as
select x.*, ci.id item_id, ci.item_type, v.version_num old_version_num,
       l.content_taxonomy_label_id old_label_id, l.label_status old_label_status,
       (select max(m.label_version) from app.content_taxonomy_labels m
        where m.content_item_id=ci.id and m.label_scope='serving') old_label_version,
       gen_random_uuid() new_version_id, gen_random_uuid() new_label_id,
       gen_random_uuid() label_decision_id, gen_random_uuid() review_assignment_id
from release_input x
join app.content_items ci on ci.content_key=x.content_key
 and ci.exam_pack_version_id='548f06be-ccf4-426d-b82b-b424137a4438'::uuid
 and ci.status='published'
join app.content_item_versions v on v.id=x.source_version_id
 and v.content_item_id=ci.id and v.version_num=1
 and v.status='retired' and v.review_status='modification_reserved'
 and v.content_hash=x.source_content_hash
join app.content_taxonomy_labels l on l.content_item_id=ci.id
 and l.label_scope='serving' and l.superseded_by is null;

do $$ begin
  if (select count(*) from release_input)<>14 or (select count(*) from release_target)<>14
  then raise exception 'TASK-0050 source preflight changed'; end if;
  if exists (select 1 from release_target t where
     (select count(*) from app.content_item_versions v where v.content_item_id=t.item_id)<>1
     or (select count(*) from app.content_item_cells c where c.content_item_id=t.item_id)<>0)
  then raise exception 'TASK-0050 unexpected versions or cells'; end if;
  if exists (select 1 from release_target t where
     t.primary_unit<>split_part(t.topic_code,'.',1)::integer
     or not t.primary_unit=any(t.required_units)
     or t.difficulty not in ('Easy','Medium','Hard')
     or not exists (select 1 from app.taxonomy_cells g
       where g.taxonomy_source_version='dae3c72e-82ca-4960-9552-1b034bd347e5'::uuid
       and g.topic_code=t.topic_code and g.skill_code=t.skill_code))
  then raise exception 'TASK-0050 topic, skill or difficulty mismatch'; end if;
  if (select count(*) from release_target where proposed_content is not null)<>12
  then raise exception 'TASK-0050 revised-content count mismatch'; end if;
end $$;

-- The prior v1 stays retired; MCQ-012's historical attempt continues to point to it.
update app.content_items ci set status='draft',updated_at=now()
from release_target t where ci.id=t.item_id;

insert into app.content_item_versions
 (id,content_item_id,version_num,stem,stimulus,prompt_json,explanation,help_text,
  content_hash,status,created_by,canonical_answer_1,canonical_answer_2,
  review_status,rubric_type,evaluator_strategy,stimulus_image_path)
select t.new_version_id,t.item_id,2,
       coalesce(t.proposed_content->>'stem',v.stem),
       case when t.proposed_content is null then v.stimulus else t.proposed_content->>'stimulus' end,
       case when t.item_type='frq' then
         coalesce(t.proposed_content->'prompt_json',v.prompt_json) ||
         jsonb_build_object('practice_modality','supplemental_hand_drawn')
       else coalesce(t.proposed_content->'prompt_json',v.prompt_json) end,
       case when t.proposed_content is null then v.explanation else t.proposed_content->>'explanation' end,
       v.help_text,md5(t.new_version_id::text),'draft',
       'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,
       case when t.proposed_content is null then v.canonical_answer_1 else t.proposed_content->>'canonical_answer_1' end,
       v.canonical_answer_2,'tutor_review_pending',v.rubric_type,v.evaluator_strategy,v.stimulus_image_path
from release_target t join app.content_item_versions v on v.id=t.source_version_id;

insert into app.mcq_choices (content_item_version_id,choice_key,choice_text,is_correct,rationale)
select t.new_version_id,c.choice_key,c.choice_text,c.is_correct,c.rationale
from release_target t join app.mcq_choices c on c.content_item_version_id=t.source_version_id
where t.item_type='mcq' and t.proposed_content is null;

insert into app.mcq_choices (content_item_version_id,choice_key,choice_text,is_correct,rationale)
select t.new_version_id,c->>'choice_key',c->>'choice_text',(c->>'is_correct')::boolean,c->>'rationale'
from release_target t cross join lateral jsonb_array_elements(t.proposed_content->'choices') c
where t.item_type='mcq' and t.proposed_content is not null;

insert into app.frq_criteria
 (content_item_version_id,criterion_key,learner_facing_text,points_possible,
  evidence_requirements,minimum_fix,accepted_variants,judgement_kind)
select t.new_version_id,c.criterion_key,c.learner_facing_text,c.points_possible,
       c.evidence_requirements,c.minimum_fix,c.accepted_variants,c.judgement_kind
from release_target t join app.frq_criteria c on c.content_item_version_id=t.source_version_id
where t.item_type='frq' and t.proposed_content is null;

insert into app.frq_criteria
 (content_item_version_id,criterion_key,learner_facing_text,points_possible,
  evidence_requirements,minimum_fix,accepted_variants,judgement_kind)
select t.new_version_id,c->>'criterion_key',c->>'learner_facing_text',
       (c->>'points_possible')::integer,
       'Earns when the response satisfies this criterion: ' || (c->>'learner_facing_text') ||
       ' Accept equivalent correct wording and values within normal rounding. Does not earn if the required element is missing, incorrect, or contradicted.',
       'To earn this point, make sure your response: ' || lower(c->>'learner_facing_text'),
       coalesce(old.accepted_variants,'[]'::jsonb),
       coalesce(old.judgement_kind,'text')
from release_target t
cross join lateral jsonb_array_elements(t.proposed_content->'prompt_json'->'criteria') c
left join app.frq_criteria old on old.content_item_version_id=t.source_version_id
 and old.criterion_key=c->>'criterion_key'
where t.item_type='frq' and t.proposed_content is not null;

-- Content hash is a stable snapshot; the serving-label guard uses taxonomy_relevant_hash.
update app.content_item_versions v set content_hash=md5(
  coalesce(v.stem,'') || E'\n' || coalesce(v.stimulus,'') || E'\n' ||
  coalesce(v.prompt_json::text,'') || E'\n' ||
  coalesce(v.canonical_answer_1,'') || E'\n' ||
  coalesce((select string_agg(c.choice_key||':'||c.choice_text||':'||c.is_correct::text||':'||coalesce(c.rationale,''),E'\n' order by c.choice_key)
            from app.mcq_choices c where c.content_item_version_id=v.id),'') || E'\n' ||
  coalesce((select string_agg(c.criterion_key||':'||c.learner_facing_text||':'||c.points_possible::text,E'\n' order by c.criterion_key)
            from app.frq_criteria c where c.content_item_version_id=v.id),'')
),updated_at=now()
from release_target t where v.id=t.new_version_id;

do $$ begin
  if exists (select 1 from release_target t where
      (t.item_type='mcq' and ((select count(*) from app.mcq_choices c where c.content_item_version_id=t.new_version_id)<>4
        or (select count(*) from app.mcq_choices c where c.content_item_version_id=t.new_version_id and c.is_correct)<>1))
      or (t.item_type='frq' and ((select count(*) from app.frq_criteria c where c.content_item_version_id=t.new_version_id)<>4
        or (select sum(c.points_possible) from app.frq_criteria c where c.content_item_version_id=t.new_version_id)<>4)))
  then raise exception 'TASK-0050 answer or rubric structural QA failed'; end if;
end $$;

insert into app.content_review_assignments
 (content_review_assignment_id,content_item_version_id,reviewer_id,review_stage,review_kind,
  status,assignment_purpose,created_by)
select t.review_assignment_id,t.new_version_id,
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,'tutor_question',t.item_type,
 'pending','owner_remediation_approval','f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid
from release_target t;

insert into app.content_review_decisions
 (content_review_assignment_id,content_item_version_id,reviewer_id,review_stage,
  tutor_score,difficulty_label,diagnostic_flag,concern_codes,note,tutor_decision,
  decision_payload,decision_hash,created_by)
select t.review_assignment_id,t.new_version_id,
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,'tutor_question',1,t.difficulty,
 false,array[]::text[],
 'TASK-0050 / APPROVAL-0258: owner directed publication of the 14 reviewed Statistics successors; independent arithmetic and rubric checks documented in the release packet; prior modification_reserved v1 retained.',
 'approve',
 jsonb_build_object('approval','APPROVAL-0258','content_key',t.content_key,
  'source_version_id',t.source_version_id,'new_version_id',t.new_version_id,
  'skill_vote_run','skill-codes-ap_statistics-20261113030247'),
 md5(t.new_version_id::text||':TASK-0050:APPROVAL-0258'),
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid
from release_target t;

update app.content_item_versions v set status='reviewed_approved',
 review_status='question_review_approved',approved_at=now(),
 approved_by='f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,updated_at=now()
from release_target t where v.id=t.new_version_id;
update app.content_items ci set status='reviewed_approved',updated_at=now()
from release_target t where ci.id=t.item_id;

insert into app.content_item_difficulty
 (content_item_version_id,difficulty,basis,rationale,confidence,proposal_run,created_by)
select t.new_version_id,t.difficulty,'calibrated_judgement',
 'TASK-0050 successor difficulty: FRQ construction/interpretation calibrated against the AP Statistics structural framework; MCQ level carried from intended_difficulty, with MCQ-017 scope repair.',
 'medium','task0050-stats-publish14-20261112',
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid
from release_target t;

insert into app.content_taxonomy_labels
 (content_taxonomy_label_id,content_item_id,label_version,label_scope,
  required_units,max_required_unit,primary_unit,assessed_topics,
  taxonomy_source_version,taxonomy_confidence,label_status,source,source_payload,
  model_run_id,created_by)
select t.new_label_id,t.item_id,t.old_label_version+1,'serving',
 t.required_units,(select max(u) from unnest(t.required_units) u),t.primary_unit,
 array[]::text[],'dae3c72e-82ca-4960-9552-1b034bd347e5'::uuid,
 'provisional','provisional_model','task0050_stats_publish14_20261112',
 jsonb_build_object('approval','APPROVAL-0258','topic',t.topic_code,'skill',t.skill_code,
  'agreement',t.agreement,'source_version_id',t.source_version_id,
  'new_version_id',t.new_version_id,'prior_label_status',t.old_label_status),
 'skill-codes-ap_statistics-20261113030247',
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid
from release_target t;

update app.content_taxonomy_labels l set superseded_by=t.new_label_id
from release_target t where l.content_taxonomy_label_id=t.old_label_id;

insert into app.content_taxonomy_validation_decisions
 (validation_decision_id,content_taxonomy_label_id,decided_by,decision,
  decision_source,reviewed_primary_unit,reviewed_required_units,notes)
select t.label_decision_id,t.new_label_id,
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,'confirmed','chat_review',
 t.primary_unit,t.required_units,
 'TASK-0050 / APPROVAL-0258 owner release instruction; skill from three-family vote or deterministic single registered candidate.'
from release_target t;

insert into app.content_item_cells
 (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,
  skill_code,is_primary,assignment_status,source,model_run_id,validated_by,
  validated_at,validation_decision_id)
select t.new_version_id,t.item_id,'dae3c72e-82ca-4960-9552-1b034bd347e5'::uuid,
 t.topic_code,null,true,'validated','task0050_stats_publish14_topic_20261112',
 'skill-codes-ap_statistics-20261113030247',
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,now(),gen_random_uuid()
from release_target t;

insert into app.content_item_cells
 (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,
  skill_code,is_primary,assignment_status,source,model_run_id,validated_by,
  validated_at,validation_decision_id)
select t.new_version_id,t.item_id,'dae3c72e-82ca-4960-9552-1b034bd347e5'::uuid,
 t.topic_code,t.skill_code,false,'validated','task0050_stats_publish14_skill_20261112',
 'skill-codes-ap_statistics-20261113030247:'||t.agreement,
 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,now(),gen_random_uuid()
from release_target t;

update app.content_taxonomy_labels l set label_status='validated',
 validated_by='f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,
 validated_at=now(),validation_decision_id=t.label_decision_id,
 validated_against_version_id=t.new_version_id,
 validated_against_taxo_hash=app.taxonomy_relevant_hash(t.new_version_id)
from release_target t where l.content_taxonomy_label_id=t.new_label_id;

update app.content_item_versions v set status='published',published_at=now(),updated_at=now()
from release_target t where v.id=t.new_version_id;
update app.content_items ci set status='published',updated_at=now()
from release_target t where ci.id=t.item_id;

do $$ begin
  if (select count(*) from release_target t join app.content_item_versions v
      on v.id=t.new_version_id and v.status='published' and v.review_status='question_review_approved')<>14
  then raise exception 'TASK-0050 version publish count mismatch'; end if;
  if exists (select 1 from release_target t where
      (select count(*) from app.content_item_versions v where v.content_item_id=t.item_id and v.status='published')<>1
      or (select count(*) from app.content_item_versions v where v.content_item_id=t.item_id and v.status='retired')<>1
      or (select count(*) from app.content_item_cells c where c.content_item_version_id=t.new_version_id and c.assignment_status='validated')<>2
      or (select count(*) from app.content_item_difficulty d where d.content_item_version_id=t.new_version_id)<>1
      or (t.item_type='frq' and not exists (select 1 from app.content_item_versions v
        where v.id=t.new_version_id and v.prompt_json->>'practice_modality'='supplemental_hand_drawn'))
      or not exists (select 1 from app.content_taxonomy_labels l where l.content_taxonomy_label_id=t.new_label_id
        and l.label_status='validated' and l.superseded_by is null
        and l.validated_against_version_id=t.new_version_id
        and l.validated_against_taxo_hash=app.taxonomy_relevant_hash(t.new_version_id)))
  then raise exception 'TASK-0050 post-release guard failed'; end if;
end $$;

select count(*) released_versions,
       count(*) filter(where proposed_content is not null) revised_versions,
       count(*) filter(where agreement='unanimous') unanimous_skills,
       count(*) filter(where agreement='majority_earned') majority_skills,
       count(*) filter(where agreement='deterministic_single_candidate') deterministic_skills
from release_target;
commit;
